using System;using UnityEngine;using MDPro3.UI.ServantUI;
namespace DuelStructure {
 static class NativeTransport {
  static bool prepared;static Vector2 stopPos,playPos,frameSize,framePos;static RectTransform whiteFrame;static OcgCoreUI ui;
  public static void Prepare(OcgCoreUI value){ui=value;if(prepared)return;stopPos=ui.ButtonStop.GetComponent<RectTransform>().anchoredPosition;playPos=ui.ButtonPlay.GetComponent<RectTransform>().anchoredPosition;float scale=ui.ButtonStop.GetComponentInParent<Canvas>().rootCanvas.scaleFactor;ui.ButtonStop.GetComponent<RectTransform>().anchoredPosition=stopPos-new Vector2(80/scale,0);ui.ButtonPlay.GetComponent<RectTransform>().anchoredPosition=playPos-new Vector2(80/scale,0);for(var parent=ui.ButtonStop.transform.parent;parent!=null;parent=parent.parent){var image=parent.GetComponent<UnityEngine.UI.Image>();var rect=parent.GetComponent<RectTransform>();if(image!=null&&rect!=null&&rect.rect.width<700&&rect.rect.height<250&&rect.rect.width>rect.rect.height*1.5f){whiteFrame=rect;frameSize=rect.sizeDelta;framePos=rect.anchoredPosition;rect.sizeDelta=frameSize+new Vector2(176/scale,0);rect.anchoredPosition=framePos-new Vector2(88/scale,0);break;}}Plugin.Instance.Log.LogInfo("TRANSPORT native scale="+scale+" frame="+whiteFrame?.name);prepared=true;}
  public static void Restore(){if(!prepared)return;ui.ButtonStop.GetComponent<RectTransform>().anchoredPosition=stopPos;ui.ButtonPlay.GetComponent<RectTransform>().anchoredPosition=playPos;if(whiteFrame!=null){whiteFrame.sizeDelta=frameSize;whiteFrame.anchoredPosition=framePos;}whiteFrame=null;prepared=false;}
  public static void Draw(){if(!prepared)return;var canvas=ui.ButtonStop.GetComponentInParent<Canvas>();var p=RectTransformUtility.WorldToScreenPoint(MDPro3.Program.instance.camera_.cameraUI,ui.ButtonStop.transform.position);var arrow=ui.ButtonPlay.GetComponent<UnityEngine.UI.Image>().sprite;float size=64;var left=new Rect(p.x-80-size/2,Screen.height-p.y-size/2,size,size);var right=new Rect(p.x+80-size/2,Screen.height-p.y-size/2,size,size);if(!NativeOcclusion.Covers(left)&&NativeUI.Renderer.Circle(left,"回溯一个时点",arrow,arrow,arrow,true))Host.Run(Host.Session.Back);if(!NativeOcclusion.Covers(right)&&NativeUI.Renderer.Circle(right,"推进一个时点",arrow,arrow,arrow))Host.Run(Host.Session.Step);var info=new Rect(Math.Max(0,p.x-180),Screen.height-p.y-87,Math.Min(360,Screen.width),28);if(!NativeOcclusion.Covers(info)){NativeUI.Renderer.Backdrop(new Rect(info.x-8,info.y-4,info.width+16,info.height+8));NativeUI.Renderer.Label(info,"时点 "+Host.Session.Number+" · 回合 "+MDPro3.DuelEditor.EditorNative.editor_turn_id(Host.Session.Handle)+(Host.Session.Waiting?" · 等待玩家 "+(Host.Session.PromptPlayer+1):""));}}
 }
}
